insert into pb_ai.eval_runs(run, fn, label, k, ids, cases) with s as (select *, (row_number() over (order by id) - 1) / 3 g from pb_ai.eval_set where id = any(array['tr2','tr3','tr4','tr5','tr6','tr7','tr8','tr9','tr10','em1','em2','sw1','sw2','sw3','sw5','wa1','wa2','wa3','wa4','wa5','wa6','pm1','pm2','pm3','pm4','pm5','pm6','pm7','st1','st3','st4','st6','st7','lo1','lo2','lo3','lo4','lo5','lo6','lo7','st5','sw4','st2','sw6','gb1','gb2','gb3','gb4','ct1','ct2','ct3','ct4','th1','th2','hy1','hy2','co1','co2','gn1','gn2','gn3','gn4','gn5','ng3','ng4','tr1','ng1','ng2','cs1','cs3','cs2','web2','ph04','ph05','ph06','ph07','ph01','ph02','ph03','ph08','ph09','ph11','brk2','brk3','geo1','geo2','geo3','loc5','loc6','svy2','cut3','tie4','tie6','dw3','dw4','eq5','tc3','tc4','tc5','eq4','tie5','tr11','tr12','tr13','ph10','brk1','brk4','nw1','nw2','svy3','svy4','nw3','nw4','nw5','nw6','nw7','nw8','nw9','nw10','nw11','tr14','cs4','cs5','nw12','nw13','nw14','nw15','nw16','nw17','nw18','nw19','nw20','nw21','nw22','nw23','nw24','nw25','nw26','sa1','sa2','sa3','sa4','sa5','sa6','sa7','sa8','sa9','sa10']))
  select '1121-lib7e-148', 'ai-next', 'lib7e: the 148 existing cases', 1000 + g, array_agg(id), jsonb_agg(jsonb_build_object('id', id, 'q', q, 'where', "where", 'level', level)
      || case when images is null then '{}'::jsonb else jsonb_build_object('images', images) end
      || case when image_ids is null then '{}'::jsonb else jsonb_build_object('image_ids', to_jsonb(image_ids)) end
      || case when feature is null then '{}'::jsonb else jsonb_build_object('feature', feature) end
      || case when model is null then '{}'::jsonb else jsonb_build_object('model', model) end) from s group by g;
select pb_ai.eval_pump('1121-lib7e-148') started, (select count(*) from pb_ai.eval_runs where run = '1121-lib7e-148') batches;
